<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);
$q=$pdo->prepare("SELECT a.public_id,a.text_commentary,a.audio_commentary_path,a.published_at,u2.username,u2.display_name,s.public_id source_public_id,s.title,s.canonical_url,s.status source_status,c.selected_text,c.screenshot_target_path,at.status transcript_status,COALESCE(at.edited_text,at.raw_text) transcript_text FROM annotations a JOIN users u2 ON u2.id=a.user_id JOIN follows f ON f.followed_user_id=a.user_id AND f.follower_user_id=? JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id LEFT JOIN annotation_transcripts at ON at.annotation_id=a.id WHERE a.visibility='public' AND a.status='published' AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker_user_id=? AND b.blocked_user_id=a.user_id) OR (b.blocker_user_id=a.user_id AND b.blocked_user_id=?)) ORDER BY a.published_at DESC LIMIT 50");$q->execute([$u['id'],$u['id'],$u['id']]);$feed=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Home · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/home.php">Home</a><a href="/explore.php">Explore</a><a href="/search.php">Search</a><a href="/research.php">Research</a><a href="/saved.php">Saved</a><a href="/notifications.php">Notifications</a><?php if(user_is_pro($pdo,$u)):?><a href="/ai.php">AI</a><?php endif?><?php if(($u['role']??'')==='admin'):?><a href="/admin/">Admin</a><?php endif?><a href="/settings.php">Settings</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">FOLLOWING</span><h1>Your Annotated feed</h1><p>Annotations from people you follow, across the web.</p></div><?php if(!$feed):?><div class="card empty">Your Following feed is empty. Discover researchers in <a href="/explore.php">Explore</a> or from the Chrome sidebar’s This Page feed.</div><?php endif?><?php foreach($feed as $a):?><article class="card annotationWebCard"><div class="meta"><strong><?=h($a['display_name'])?></strong> @<?=h($a['username'])?> · <?=h($a['published_at'])?> <?php if($a['source_status']==='edited'):?><span class="badge warn">Edited source</span><?php endif?></div><h2><a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['title']?:$a['canonical_url'])?></a></h2><?php if($a['text_commentary']):?><p class="commentary"><?=nl2br(h($a['text_commentary']))?></p><?php endif?><?php if($a['selected_text']):?><blockquote><?=h($a['selected_text'])?></blockquote><?php endif?><?php if($a['screenshot_target_path']):?><img class="snapshot" src="<?=h($a['screenshot_target_path'])?>" alt="Preserved annotation snapshot"><?php endif?><?php if($a['audio_commentary_path']):?><audio class="wideAudio" controls src="<?=h($a['audio_commentary_path'])?>"></audio><details><summary>Transcript · <?=h($a['transcript_status']?:'queued')?></summary><?php if($a['transcript_text']):?><p><?=nl2br(h($a['transcript_text']))?></p><?php else:?><p class="meta">Transcription is still processing.</p><?php endif?></details><?php endif?><div class="inlineActions"><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a><a href="<?=h($a['canonical_url'])?>" target="_blank" rel="noopener">Original source ↗</a></div></article><?php endforeach?></section><aside><div class="card"><h3>Research from the page itself</h3><p>Use the Chrome sidebar to capture passages, screenshots, media clips and audio commentary while you browse.</p></div></aside></main></body></html>
